te-columns:repeat(3,1fr);gap:14px}.subject-progress-card{position:relative;display:block;min-width:0;padding:20px;border:1px solid #e0e6f3;border-radius:23px;background:#fff;color:inherit;text-decoration:none;box-shadow:0 14px 35px rgba(44,56,115,.08);overflow:hidden;transition:.23s}.subject-progress-card:hover{transform:translateY(-5px);border-color:#aaa0ee;box-shadow:0 20px 43px rgba(50,57,132,.14)}.subject-head{display:flex;align-items:center;justify-content:space-between;gap:10px}.subject-name{display:flex;align-items:center;min-width:0;gap:10px}.subject-icon{display:grid;place-items:center;flex:0 0 43px;width:43px;height:43px;border-radius:14px;background:linear-gradient(135deg,#eeeaff,#e4f6ff);font-size:1.25rem}.subject-name strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.subject-percent{color:#5746c9;font-weight:950}.subject-bar{height:9px;margin:18px 0 10px;border-radius:999px;background:#edf0f8;overflow:hidden}.subject-bar span{display:block;width:0;height:100%;border-radius:inherit;background:linear-gradient(90deg,#6452df,#28bfe4);box-shadow:0 0 12px rgba(50,190,226,.3);transition:width .9s cubic-bezier(.22,.7,.2,1)}.subject-meta{display:flex;justify-content:space-between;gap:10px;color:var(--muted);font-size:.72rem}.subject-meta b{color:#36405e}.progress-lower{display:grid;grid-template-columns:1.2fr .8fr;gap:18px;margin-top:30px}.results-panel,.milestone-panel{padding:24px;border-radius:27px}.results-panel{background:#fff}.quiz-list{display:grid;gap:10px;margin-top:16px}.quiz-result{display:grid;grid-template-columns:50px minmax(0,1fr) auto;align-items:center;gap:13px;padding:12px;border:1px solid #e5e9f3;border-radius:17px;color:inherit;text-decoration:none;transition:.2s}.quiz-result:hover{border-color:#aba1ee;background:#faf9ff;transform:translateX(3px)}.quiz-score{display:grid;place-items:center;width:48px;height:48px;border-radius:15px;background:linear-gradient(135deg,#ece9ff,#e4f7ff);color:#4d40ba;font-size:.78rem;font-weight:950}.quiz-copy{min-width:0}.quiz-copy strong,.quiz-copy small{display:block}.quiz-copy strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.quiz-copy small{margin-top:3px;color:var(--muted)}.quiz-status{padding:5px 8px;border-radius:999px;background:#fff1df;color:#9c6017;font-size:.65rem;font-weight:900}.quiz-status.passed{background:#e4f9f1;color:#087a5d}.empty-progress{padding:25px;border:1px dashed #cdd5e8;border-radius:18px;text-align:center;color:var(--muted)}.milestone-panel{position:relative;overflow:hidden;background:linear-gradient(145deg,#17164e,#20266d);color:#fff;box-shadow:0 20px 46px rgba(28,31,99,.2)}.milestone-panel:after{content:'✦';position:absolute;right:-15px;top:-25px;color:rgba(255,255,255,.06);font-size:9rem}.milestone-panel h2{position:relative;margin:10px 0 7px;color:#fff}.milestone-panel>p{position:relative;color:#afbbe3}.milestone-track{position:relative;margin:23px 0 17px;height:10px;border-radius:999px;background:rgba(255,255,255,.1);overflow:hidden}.milestone-track span{display:block;width:0;height:100%;border-radius:inherit;background:linear-gradient(90deg,#ffe36d,#55eac7);transition:width 1s ease}.milestone-target{position:relative;padding:16px;border:1px solid rgba(255,255,255,.13);border-radius:17px;background:rgba(255,255,255,.07)}.milestone-target strong{display:block;font-size:1.2rem}.milestone-target small{display:block;margin-top:4px;color:#aebce5}.achievement-row{position:relative;display:flex;gap:8px;margin-top:14px}.achievement{display:grid;place-items:center;width:44px;height:44px;border-radius:14px;background:rgba(255,255,255,.09);filter:grayscale(1);opacity:.45}.achievement.unlocked{background:rgba(255,223,99,.17);filter:none;opacity:1;box-shadow:0 0 18px rgba(255,219,91,.12)}.reveal-progress{opacity:0;transform:translateY(15px);transition:opacity .5s ease,transform .5s ease}.reveal-progress.visible{opacity:1;transform:none}@keyframes progressOrbit{to{transform:rotate(360deg)}}@property --value{syntax:'<number>';inherits:false;initial-value:0}@media(max-width:920px){.subject-progress-grid{grid-template-columns:1fr 1fr}.progress-lower{grid-template-columns:1fr}.stats-ribbon{grid-template-columns:1fr 1fr}}@media(max-width:700px){.progress-world{margin-inline:-1px}.progress-hero{grid-template-columns:1fr;min-height:0;padding:27px 20px;border-radius:27px;text-align:center}.progress-eyebrow,.progress-focus{justify-content:center}.progress-hero h1{font-size:2.65rem}.progress-hero-copy>p{font-size:.88rem}.progress-orbit{margin-top:3px}.progress-ring{width:190px;height:190px}.progress-ring-content strong{font-size:2.9rem}.stats-ribbon{gap:9px}.stat-tile{min-height:115px;padding:15px}.stat-tile strong{font-size:1.4rem}.section-heading{align-items:flex-start;flex-direction:column;gap:7px}.section-heading p{text-align:left}.subject-progress-grid{grid-template-columns:1fr}.progress-lower{gap:12px}.results-panel,.milestone-panel{padding:18px}.quiz-result{grid-template-columns:44px minmax(0,1fr)}.quiz-status{grid-column:2;justify-self:start}.subject-progress-card{padding:17px}}@media(max-width:400px){.progress-hero h1{font-size:2.25rem}.stats-ribbon{grid-template-columns:1fr}.stat-tile{display:grid;grid-template-columns:42px 1fr;column-gap:12px;align-items:center;min-height:0}.stat-tile strong{margin:0}.stat-tile small{grid-column:2}.progress-focus{gap:6px}.progress-focus span{padding:7px 9px}}@media(prefers-reduced-motion:reduce){.progress-hero:before{animation:none}.reveal-progress{opacity:1;transform:none}.subject-bar span,.milestone-track span,.progress-ring{transition:none}}
</style>
