  <div class="progress-orbit"><div class="progress-ring" data-ring="<?=$percent?>"><div class="progress-ring-content"><strong><span class="count-up" data-value="<?=$percent?>">0</span>%</strong><span>Overall complete</span></div><div class="progress-ring-note"><?=$percent>=100?'Mastered':'Next · '.$nextMilestone.'%'?></div></div></div>
