<script>
(()=>{const reveal=document.querySelectorAll('.reveal-progress');const activate=element=>{element.classList.add('visible');element.querySelectorAll('[data-width]').forEach(bar=>bar.style.width=bar.dataset.width)};if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){activate(entry.target);observer.unobserve(entry.target)}}),{threshold:.1});reveal.forEach(item=>observer.observe(item))}else reveal.forEach(activate);const ring=document.querySelector('[data-ring]');requestAnimationFrame(()=>{if(ring)ring.style.setProperty('--value',ring.dataset.ring)});document.querySelectorAll('.count-up').forEach(counter=>{const target=Number(counter.dataset.value)||0,start=performance.now(),duration=850;const tick=now=>{const progress=Math.min(1,(now-start)/duration);counter.textContent=Math.round(target*(1-Math.pow(1-progress,3))).toLocaleString();if(progress<1)requestAnimationFrame(tick)};requestAnimationFrame(tick)})})();
</script>
